    <script>
    // Fallback for browsers that don’t support requestIdleCallback
    window.requestIdleCallback = window.requestIdleCallback || function(cb) {
        return setTimeout(cb, 1);
    };

    requestIdleCallback(() => {
        const swiperScript = document.createElement("script");
        swiperScript.src = "https://cdn.jsdelivr.net/npm/swiper@10/swiper-bundle.min.js";
        swiperScript.onload = () => {
            const configs = {
                mySwiper2: 4,
                mySwiper3: 2,
                mySwiper4: 3,
                mySwiper5: 4,
                mySwiper6: 2,
                mySwiper7: 2,
            };

            Object.entries(configs).forEach(([className, slidesView]) => {
                new Swiper(`.${className}`, {
                    slidesPerView: slidesView,
                    spaceBetween: 30,
                    loop: true,
                    freeMode: true,
                    breakpoints: {
                        280: {
                            slidesPerView: 1,
                            spaceBetween: 10
                        },
                        320: {
                            slidesPerView: 1,
                            spaceBetween: 10
                        },
                        480: {
                            slidesPerView: 2,
                            spaceBetween: 10
                        },
                        768: {
                            slidesPerView: Math.max(2, slidesView - 1),
                            spaceBetween: 10,
                        },
                        1200: {
                            slidesPerView: slidesView,
                            spaceBetween: 10
                        },
                    },
                    autoplay: {
                        delay: 3500,
                        disableOnInteraction: true,
                        pauseOnMouseEnter: true,
                    },
                    navigation: {
                        nextEl: `.swiper-button-next${className.slice(-1)}`,
                        prevEl: `.swiper-button-prev${className.slice(-1)}`,
                    },
                    pagination: {
                        el: `.swiper-pagination${className.slice(-1)}`,
                        clickable: true,
                    },
                });
            });
        };
        document.body.appendChild(swiperScript);
    });
    </script>

    <script>
    document.addEventListener("DOMContentLoaded", () => {
        const cards = document.querySelectorAll(".testimonial-card");

        cards.forEach((card) => {
            const text = card.querySelector(".testimonial-text");
            const btn = card.querySelector(".read-more-btn");
            setTimeout(() => {
                const isClamped = text.scrollHeight > text.clientHeight;

                if (!isClamped) {
                    btn.style.display = "none";
                }
            }, 100);

            btn.addEventListener("click", () => {
                text.classList.toggle("expanded");
                btn.textContent = text.classList.contains("expanded") ?
                    "Read less" :
                    "Read more";
            });
        });
    });
    </script>

