    <!-- testimonial swiper -->
    <script>
    window.addEventListener("load", function() {
        const swiperContainer = document.querySelector(".scrollHeaderSwiper .swiper-wrapper");

        if (swiperContainer) {
            const slides = swiperContainer.querySelectorAll(".swiper-slide");

            if (slides.length < 4) {
                const needed = 4 - slides.length;
                const fragment = document.createDocumentFragment();
                for (let i = 0; i < needed; i++) {
                    fragment.appendChild(slides[i % slides.length].cloneNode(true));
                }
                swiperContainer.appendChild(fragment); // Append once, reduce layout thrashing
            }

            // Wait for layout to settle before initializing Swiper
            requestAnimationFrame(() => {
                const swiperHeader = new Swiper(".scrollHeaderSwiper", {
                    slidesPerView: "auto",
                    loop: true,
                    speed: 6000,
                    autoplay: {
                        delay: 0,
                        disableOnInteraction: false,
                    },
                    allowTouchMove: false,
                });

                const swiperEl = document.querySelector(".scrollHeaderSwiper");
                swiperEl.addEventListener("mouseenter", () => swiperHeader.autoplay.stop());
                swiperEl.addEventListener("mouseleave", () => swiperHeader.autoplay.start());
            });
        }
    });
    </script>

    <!-- Lazy load YouTube embeds -->
    <script>
    document.addEventListener("DOMContentLoaded", () => {
        const videoMap = {
            Mlfirstvideo: "7ulfF4f0ZBM",
            Mlsecondvideo: "kT39ni_zmKQ",
            Mlthirdvideo: "TwJljHVWEbY",
            Mlfourvideo: "GNCITvX6dXg"
        };

        Object.entries(videoMap).forEach(([btnId, videoId]) => {
            const button = document.getElementById(btnId);
            if (button) {
                button.addEventListener("click", () => {
                    const iframe = document.createElement("iframe");
                    iframe.className = "ml-with-iot-preview-vdo";
                    iframe.id = "Previewframevideo";
                    iframe.src = `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0`;
                    iframe.sandbox = "allow-scripts allow-same-origin allow-presentation";
                    iframe.title = "YouTube video player";
                    iframe.loading = "lazy";
                    iframe.frameBorder = "0";
                    iframe.allow =
                        "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture";
                    iframe.allowFullscreen = true;

                    const oldIframe = document.getElementById("Previewframevideo");
                    if (oldIframe) oldIframe.replaceWith(iframe);
                });
            }
        });
    });
    </script>

    <!-- Scroll-triggered banner display -->
    <script>
    document.addEventListener("DOMContentLoaded", () => {
        const bottomStripSec = document.querySelector(".down-fixed-bottom-dv");
        window.addEventListener("scroll", () => {
            if (window.scrollY < 1700) {
                bottomStripSec.classList.add("d-none");
            } else {
                bottomStripSec.classList.remove("d-none");
            }
        });
    });
    </script>

    <script defer>
    function getTimeRemaining(endTime) {
        const total = Date.parse(endTime) - Date.parse(new Date());
        const seconds = Math.floor((total / 1000) % 60);
        const minutes = Math.floor((total / 1000 / 60) % 60);
        const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
        const days = Math.floor(total / (1000 * 60 * 60 * 24));

        return {
            total,
            days,
            hours,
            minutes,
            seconds
        };
    }

    function getEndOfMonth() {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth() + 1; // Months are 0-based, so add 1
        const endOfMonth = new Date(year, month, 0, 23, 59, 59); // Last day of the current month at 23:59:59
        return endOfMonth;
    }

    function padZero(number) {
        return number < 10 ? '0' + number : number;
    }

    function initializeClock() {
        // const countdownElement = document.getElementById('countdown');
        const countdownElement2 = document.getElementById('countdown2');
        const endTime = getEndOfMonth();

        function updateClock() {
            const t = getTimeRemaining(endTime);
            // countdownElement.innerHTML = `
            //     <p><span>${padZero((t.days <= 0) ? "0" : t.days)}</span>Days</p> :
            //     <p><span>${padZero((t.hours <= 0) ? "0" : t.hours)}</span>Hours</p> :
            //     <p><span>${padZero((t.minutes <= 0) ? "0" : t.minutes)}</span>Minutes</p> :
            //     <p><span>${padZero((t.seconds <= 0) ? "0" : t.seconds)}</span>Seconds</p>
            // `;
            countdownElement2.innerHTML = `
                <p><span>${padZero((t.days <= 0) ? "0" : t.days)}</span>Days</p>
                <p><span>${padZero((t.hours <= 0) ? "0" : t.hours)}</span>Hours</p>
                <p><span>${padZero((t.minutes <= 0) ? "0" : t.minutes)}</span>Minutes</p>
                <p><span>${padZero((t.seconds <= 0) ? "0" : t.seconds)}</span>Seconds</p>
            `;
            if (t.total <= 0) {
                clearInterval(timeInterval);
                // countdownElement.innerHTML = "Time's up!";
                countdownElement2.innerHTML = "Time's up!";
            }
        }

        updateClock(); // run function once at first to avoid delay
        const timeInterval = setInterval(updateClock, 1000);
    }
    window.onload = initializeClock;
    const today = new Date();
    const lastMonthLastDate = new Date(today.getFullYear(), today.getMonth(), 0);
    const formattedDate = lastMonthLastDate.toLocaleDateString("en-US", {
        day: "numeric",
        month: "long",
        year: "numeric"
    });
    document.getElementById("month-last-date").textContent = formattedDate;
    // document.getElementById("month-last-date2").textContent = formattedDate;
    // document.getElementById("month-last-date3").textContent = formattedDate;
    </script>


